+// Direct old/current controls. `old::append` is the pre-change body, verbatim.
+// ASSUMED helpers (tests.rs was not supplied; bind these to the existing ones):
+//   plan(loans: &[(&str /*site*/, u32 /*id*/)],
+//        live_after: &[(&str /*expr*/, &[u32])]) -> LoanPlan
+//   program() -> ResolvedProgram
+//   with_ledger(limit: Option<usize>, f: impl FnOnce() -> R) -> (R, usize /*charged*/)
+// Also assumes Diagnostic and the projected key/value types implement Debug.
+use super::super::tests::{plan, program, with_ledger};
+use super::*;
+
+struct Run {
+    error: Option<String>,
+    charged: usize,
+    view: String,
+    ordinals: Vec<usize>,
+    shape: [(usize, usize); 3],
+}
+
+fn step(
+    storage: &mut Storage<'_>,
+    plan: LoanPlan,
+    payer: Payer<'_>,
+    legacy: bool,
+) -> Result<(), Diagnostic> {
+    if legacy {
+        old::append(storage, plan, payer)
+    } else {
+        append(storage, plan, payer)
+    }
+}
+
+fn drive(plans: Vec<LoanPlan>, limit: Option<usize>, legacy: bool) -> Run {
+    let program = program();
+    let (run, charged) = with_ledger(limit, || {
+        let mut storage = Storage::new(&program);
+        let payer = Payer::current();
+        let mut error = None;
+        for plan in plans {
+            if let Err(e) = step(&mut storage, plan, payer, legacy) {
+                error = Some(format!("{e:?}"));
+                break;
+            }
+        }
+        Run {
+            error,
+            charged: 0,
+            view: format!("{:?}", storage.projection()),
+            ordinals: storage.projection().1.iter().map(|e| e.1).collect(),
+            shape: storage.scratch_shape(),
+        }
+    });
+    Run { charged, ..run }
+}
+
+// n equal-size plans with disjoint sites/ids/expressions.
+fn repeated(n: u32) -> Vec<LoanPlan> {
+    (0..n)
+        .map(|i| {
+            let (a, b) = (format!("a{i}"), format!("b{i}"));
+            plan(
+                &[(a.as_str(), 2 * i), (b.as_str(), 2 * i + 1)],
+                &[(a.as_str(), &[2 * i, 2 * i + 1][..])],
+            )
+        })
+        .collect()
+}
+
+#[test]
+fn duplicates_match_legacy_in_order_and_last_local_wins() {
+    let cases: [fn() -> Vec<LoanPlan>; 4] = [
+        // same loan id twice locally: the last occurrence's origin index wins
+        || vec![plan(&[("a", 1), ("b", 1)], &[("e", &[1][..])])],
+        // same live key repeated
+        || vec![plan(&[("a", 1)], &[("e", &[1][..]), ("e", &[1][..])])],
+        // same (site, cause) identity twice
+        || vec![plan(&[("a", 1), ("a", 2)], &[])],
+        // unknown loan is reported before the duplicate check
+        || vec![plan(&[("a", 1)], &[("e", &[9, 9][..])])],
+    ];
+    for (n, case) in cases.iter().enumerate() {
+        let (new, old) = (drive(case(), None, false), drive(case(), None, true));
+        assert_eq!(
+            (&new.error, &new.view, &new.ordinals),
+            (&old.error, &old.view, &old.ordinals),
+            "case {n}"
+        );
+    }
+    assert_eq!(drive(cases[0](), None, false).ordinals, [1]);
+}
+
+#[test]
+fn scratch_is_empty_between_plans_and_capacity_is_retained() {
+    let big = plan(&[("a", 1), ("b", 2), ("c", 3)], &[("e", &[1, 2, 3][..])]);
+    let small = plan(&[("d", 4)], &[("f", &[4][..])]);
+    let run = drive(vec![big, small], None, false);
+    assert!(run.error.is_none());
+    assert!(run.shape.iter().all(|(len, _)| *len == 0));
+    assert!(run.shape.iter().all(|(_, cap)| *cap >= 3));
+    let refused = drive(vec![plan(&[("a", 1)], &[("e", &[9][..])])], None, false);
+    assert!(refused.error.is_some());
+    assert!(refused.shape.iter().all(|(len, _)| *len == 0));
+}
+
+#[test]
+fn exact_short_refuses_in_both_and_equal_plans_charge_less() {
+    for legacy in [false, true] {
+        let free = drive(repeated(4), None, legacy);
+        assert!(free.error.is_none());
+        assert!(drive(repeated(4), Some(free.charged), legacy).error.is_none());
+        assert!(drive(repeated(4), Some(free.charged - 1), legacy).error.is_some());
+    }
+    let (new, old) = (drive(repeated(4), None, false), drive(repeated(4), None, true));
+    assert_eq!(new.view, old.view);
+    assert!(new.charged < old.charged);
+}
+
+#[test]
+fn refusal_is_sticky_and_leaves_scratch_empty() {
+    for legacy in [false, true] {
+        let free = drive(repeated(4), None, legacy);
+        let (after, _) = with_ledger(Some(free.charged - 1), || {
+            let program = program();
+            let mut storage = Storage::new(&program);
+            let payer = Payer::current();
+            let first = repeated(4)
+                .into_iter()
+                .try_for_each(|p| step(&mut storage, p, payer, legacy));
+            assert!(first.is_err());
+            let again = step(&mut storage, plan(&[], &[]), payer, legacy);
+            (again.is_err(), storage.scratch_shape())
+        });
+        assert!(after.0);
+        assert!(after.1.iter().all(|(len, _)| *len == 0));
+    }
+}
+
+struct EmptyAtDrop<'a>(Storage<'a>);
+impl Drop for EmptyAtDrop<'_> {
+    fn drop(&mut self) {
+        assert!(self.0.scratch_shape().iter().all(|(len, _)| *len == 0));
+    }
+}
+
+// Capacity release itself is not observable without a counting allocator;
+// this only pins "empty at receiver Drop" for success, refusal, and legacy.
+#[test]
+fn scratch_is_empty_when_receiver_drops() {
+    let program = program();
+    let mut ok = EmptyAtDrop(Storage::new(&program));
+    for p in repeated(3) {
+        assert!(append(&mut ok.0, p, Payer::current()).is_ok());
+    }
+    let mut bad = EmptyAtDrop(Storage::new(&program));
+    let unknown = plan(&[("a", 1)], &[("e", &[9][..])]);
+    assert!(append(&mut bad.0, unknown, Payer::current()).is_err());
+    // Control: the legacy body never touches scratch.
+    let mut old = EmptyAtDrop(Storage::new(&program));
+    assert!(old::append(&mut old.0, repeated(1).remove(0), Payer::current()).is_ok());
+    assert_eq!(old.0.scratch_shape(), [(0, 0); 3]);
+}
